  background-color: #E5E7EB;
}

.fab-color-warning {
  background-color: #FB923C;
}

.fab-color-warning:hover:not(:disabled) {
  background-color: #F97316;
}

.fab-color-success {
  background-color: #16A34A;
}

.fab-color-success:hover:not(:disabled) {
  background-color: #15803D;
}

